userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="playMotion">Play Motion</button>
<label>
  Time (Position)
  <input type="range" id="time" min="0" max="4" step="0.01" value="0">
</label>
<label>
  View Mode
  <select id="viewMode">
    <option value="3D Camera Strip">3D Camera Strip</option>
    <option value="Image-Plane Flow">Image-Plane Flow</option>
  </select>
</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// 5 stationary camera frustums -> Group with Sphere (pinhole), LineSegments (frustum), Line (midline)
// Thick red arrows -> Group with Cylinder (shaft), Cone (head)
// 3D reference points -> Group of 25 Spheres
// Active camera -> Group (blue frustum) with ArrowHelpers for optical flow

const sceneElements = new THREE.Group();
scene.add(sceneElements);

// Generator for camera frustum geometry
function createCameraFrustum(color, isStationary) {
  const group = new THREE.Group();

  // Pinhole (solid dot)
  const mat = new THREE.MeshBasicMaterial({ color: color });
  const pinhole = new THREE.Mesh(new THREE.SphereGeometry(isStationary ? 0.15 : 0.18, 16, 16), mat);
  group.add(pinhole);

  // Frustum lines
  const pts = [];
  const hw = 0.4; // half width (Z)
  const hh = 0.6; // half height (Y)
  const corners = [
    [1, hh, hw], [1, -hh, hw],
    [1, -hh, -hw], [1, hh, -hw]
  ];

  // Rays from pinhole
  corners.forEach(c => {
    pts.push(new THREE.Vector3(0, 0, 0), new THREE.Vector3(...c));
  });

  // Image plane rectangle
  for(let i = 0; i < 4; i++) {
    pts.push(new THREE.Vector3(...corners[i]));
    pts.push(new THREE.Vector3(...corners[(i + 1) % 4]));
  }

  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const lines = new THREE.LineSegments(geom, new THREE.LineBasicMaterial({ color: color }));
  group.add(lines);

  // Faint vertical midline
  const midPts = [new THREE.Vector3(1, hh, 0), new THREE.Vector3(1, -hh, 0)];
  const midGeom = new THREE.BufferGeometry().setFromPoints(midPts);
  const midLine = new THREE.Line(midGeom, new THREE.LineBasicMaterial({ color: isStationary ? 0x999999 : color }));
  group.add(midLine);

  return group;
}

// 1. Build 5 stationary cameras
for (let i = 0; i < 5; i++) {
  const cam = createCameraFrustum(0x000000, true);
  cam.position.x = i * 2.5;
  sceneElements.add(cam);
}

// 2. Build thick red arrows along the optical axis path
const arrowXs = [-1.25, 1.25, 3.75, 6.25, 8.75, 11.25];
const arrowMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
const shaftGeom = new THREE.CylinderGeometry(0.04, 0.04, 0.6, 12);
const headGeom = new THREE.ConeGeometry(0.12, 0.4, 12);

arrowXs.forEach(xPos => {
  const arrowGroup = new THREE.Group();

  const shaft = new THREE.Mesh(shaftGeom, arrowMat);
  shaft.rotation.z = -Math.PI / 2;
  shaft.position.x = -0.2;
  arrowGroup.add(shaft);

  const head = new THREE.Mesh(headGeom, arrowMat);
  head.rotation.z = -Math.PI / 2;
  head.position.x = 0.3;
  arrowGroup.add(head);

  arrowGroup.position.x = xPos;
  sceneElements.add(arrowGroup);
});

// 3. Build 3D reference points far ahead in the scene
const pointsData = [];
const pointsGroup = new THREE.Group();
const ptMat = new THREE.MeshBasicMaterial({ color: 0x444444 });
const ptGeom = new THREE.SphereGeometry(0.2, 16, 16);

for(let i = 0; i < 25; i++) {
  // Pseudo-random scattering ahead of the path (X=15 to 25)
  const x = 15 + (Math.sin(i * 123.45) * 0.5 + 0.5) * 10;
  const y = Math.sin(i * 321.12) * 4;
  const z = Math.sin(i * 456.78) * 4;

  const pt = new THREE.Mesh(ptGeom, ptMat);
  pt.position.set(x, y, z);
  pointsGroup.add(pt);
  pointsData.push(new THREE.Vector3(x, y, z));
}
scene.add(pointsGroup);

// 4. Build Active Moving Camera and its Flow Vectors
const activeCamera = createCameraFrustum(0x1a66cc, false);
activeCamera.position.y = 0.005; // tiny offset to prevent precise z-fighting with stationary cameras
const flowGroup = new THREE.Group();
activeCamera.add(flowGroup);
scene.add(activeCamera);

const flowArrows = [];
for(let i = 0; i < pointsData.length; i++) {
  // Init placeholder vectors; updated dynamically
  const arrow = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 0), 1, 0x1a66cc, 0.1, 0.06);
  flowGroup.add(arrow);
  flowArrows.push(arrow);
}

// 5. UI and Animation bindings
const playBtn = document.getElementById('playMotion');
const timeSlider = document.getElementById('time');
const viewModeSelect = document.getElementById('viewMode');

let isPlaying = false;

playBtn.addEventListener('click', () => {
  isPlaying = !isPlaying;
  playBtn.textContent = isPlaying ? "Pause Motion" : "Play Motion";
  playBtn.classList.toggle('active', isPlaying);
  if (isPlaying && parseFloat(timeSlider.value) >= 4) {
    timeSlider.value = 0;
  }
});

timeSlider.addEventListener('input', () => {
  isPlaying = false;
  playBtn.textContent = "Play Motion";
  playBtn.classList.remove('active');
  updateState();
});

viewModeSelect.addEventListener('change', applyViewMode);

const foeLabel = addLabel('Focus of Expansion', new THREE.Vector3(), {
  color: '#1a66cc',
  background: 'rgba(255,255,255,0.85)',
  offset: [0, 20]
});

function updateState() {
  const t = parseFloat(timeSlider.value);
  const activeX = t * 2.5;
  activeCamera.position.x = activeX;

  const flowScale = 15; // Visual scaling factor for flow velocity

  for(let i = 0; i < pointsData.length; i++) {
    const P = pointsData[i];
    const px = P.x - activeX; // Depth relative to camera

    if (px > 1) {
      // Projected image plane coordinates (f = 1)
      const y = P.y / px;
      const z = P.z / px;

      // Optical flow field equation (radial expansion from forward translation)
      const vy = (y / px) * flowScale;
      const vz = (z / px) * flowScale;

      const dir = new THREE.Vector3(0, vy, vz);
      const len = dir.length();

      if (len > 0.001) {
        flowArrows[i].visible = true;
        flowArrows[i].setDirection(dir.normalize());
        // Cap max length and dynamically scale arrowhead
        flowArrows[i].setLength(Math.min(len, 2.5), Math.min(len * 0.3, 0.15), Math.min(len * 0.2, 0.1));
        flowArrows[i].position.set(1.01, y, z); // slight X offset prevents z-fighting with the image plane box
      } else {
        flowArrows[i].visible = false;
      }
    } else {
      flowArrows[i].visible = false;
    }
  }

  // Position FOE label exactly at the optical center on the image plane
  if (viewModeSelect.value === 'Image-Plane Flow') {
    foeLabel.pos.set(activeX + 1, 0, 0);
  } else {
    foeLabel.pos.set(9999, 9999, 9999); // Hide safely
  }
}

function applyViewMode() {
  if (viewModeSelect.value === 'Image-Plane Flow') {
    controls.enabled = false;
    // Set perspective FOV to exactly frame the 1.2 height at distance 1
    camera.fov = THREE.MathUtils.radToDeg(2 * Math.atan(0.6));
    camera.updateProjectionMatrix();
    updateState(); // Ensure FOE label is shown
  } else {
    controls.enabled = true;
    camera.fov = 35; // Restore default FOV
    camera.updateProjectionMatrix();
    setCameraView({
      projection: 'perspective',
      azimuthDeg: 20,
      elevationDeg: 10,
      rollDeg: 0,
      heightFraction: 0.5
    });
    updateState(); // Ensure FOE label is hidden
  }
}

let lastTime = performance.now();
function customLoop() {
  requestAnimationFrame(customLoop);
  const now = performance.now();
  const dt = (now - lastTime) / 1000;
  lastTime = now;

  if (isPlaying) {
    let t = parseFloat(timeSlider.value);
    t += dt * 0.6; // Speed of motion
    if (t > 4) {
      t = 0; // Loop seamlessly
    }
    timeSlider.value = t;
    updateState();
  }

  // Force camera into the exact pinhole position overriding any lingering OrbitControls damping
  if (viewModeSelect.value === 'Image-Plane Flow') {
    const activeX = activeCamera.position.x;
    camera.position.set(activeX, 0, 0);
    camera.up.set(0, 1, 0);
    controls.target.set(activeX + 1, 0, 0);
    camera.lookAt(activeX + 1, 0, 0);
  }
}

// 6. Labels and tooltips
addLabel('Start Position', new THREE.Vector3(0, -1.6, 0), { color: '#444' });
addLabel('End Position', new THREE.Vector3(10, -1.6, 0), { color: '#444' });
addLabel('Path of Motion', new THREE.Vector3(5, 0.6, 0), { color: '#ff0000' });
addLabel('3D Scene Points', new THREE.Vector3(20, 5, 0), { color: '#444' });

registerInteractive(activeCamera, {
  title: "Translating Camera",
  body: "This camera moves purely forward along its optical axis. Because there is no sideways velocity, objects in its view undergo pure radial expansion."
});

// Setup initial state and layout
updateState();
applyViewMode();
customLoop();

window.goToStep = function(stepIndex) {
  const steps = [
    { time: 0, viewMode: "3D Camera Strip" },
    { time: 0, viewMode: "Image-Plane Flow" }
  ];
  if (steps[stepIndex]) {
    timeSlider.value = steps[stepIndex].time;
    viewModeSelect.value = steps[stepIndex].viewMode;
    isPlaying = false;
    playBtn.textContent = "Play Motion";
    playBtn.classList.remove('active');
    applyViewMode();
    updateState();
  }
};
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

