  // Frustum lines
  const pts = [];
  const hw = 0.5; // half width (Z)
  const hh = 0.6; // half height (Y)
  const depth = 0.8; // X depth of frustum

  const corners = [
    [depth, hh, hw], [depth, -hh, hw],
    [depth, -hh, -hw], [depth, hh, -hw]
  ];

  // Rays from pinhole
  corners.forEach(c => {
    pts.push(new THREE.Vector3(0, 0, 0), new THREE.Vector3(...c));
  });

  // Image plane rectangle
  for(let i = 0; i < 4; i++) {
    pts.push(new THREE.Vector3(...corners[i]));
    pts.push(new THREE.Vector3(...corners[(i + 1) % 4]));
  }

  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const lines = new THREE.LineSegments(geom, new THREE.LineBasicMaterial({ color: color, linewidth: 2 }));

  // Faint vertical midline (from previous spec, keeping it simple or removing if not in source)
  // Source has a line indicating the plane depth on the side, or just the wireframe. 
  // Standard wireframe is sufficient.

  group.add(lines);

  return group;
}

const spacing = 3.5; // Increase spacing so frustums don't overlap

