// @FIGURE_CODE_BEGIN
// 5 stationary camera frustums -> Group with Sphere (pinhole), LineSegments (frustum edges)
// Thick red arrows -> Group with single continuous Cylinder (shaft) and Cones (heads)

const spacing = 2.5;
const numCameras = 5;

const sceneElements = new THREE.Group();
scene.add(sceneElements);

function createCameraFrustum(color) {
  const group = new THREE.Group();

  // Pinhole (solid dot) - sized larger than the ray to ensure it renders visibly
  const mat = new THREE.MeshBasicMaterial({ color: color });
  const pinhole = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 16), mat);
  group.add(pinhole);

  // Frustum lines
  const pts = [];
  const hw = 0.6; // half width (Z)
  const hh = 0.8; // half height (Y)
  const depth = 1.0; // X depth of frustum

  const corners = [
    [depth, hh, hw], [depth, -hh, hw],
    [depth, -hh, -hw], [depth, hh, -hw]
  ];

  // Rays from pinhole to corners
  corners.forEach(c => {
    pts.push(new THREE.Vector3(0, 0, 0), new THREE.Vector3(...c));
  });

  // Image plane rectangle (back face)
  for(let i = 0; i < 4; i++) {
    pts.push(new THREE.Vector3(...corners[i]));
    pts.push(new THREE.Vector3(...corners[(i + 1) % 4]));
  }

  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const lines = new THREE.LineSegments(geom, new THREE.LineBasicMaterial({ color: color }));
  group.add(lines);

  return group;
}

// 1. Build the 5 stationary cameras
for (let i = 0; i < numCameras; i++) {
  const cam = createCameraFrustum(0x000000);
  cam.position.x = i * spacing;

  registerInteractive(cam, {
    title: `Camera ${i + 1}`,
    body: `Frustum representing the field of view for camera ${i + 1}.`
  });

  sceneElements.add(cam);
}

// 2. Build the single continuous red ray and its arrowheads
const rayGroup = new THREE.Group();

const shaftRadius = 0.04;
const headRadius = 0.15;
const headLength = 0.4;

// The continuous ray starts before the first camera and ends after the last one
const startX = -1.5;
const endX = (numCameras - 1) * spacing + 1.8; 
const shaftLength = endX - startX;
const shaftCenterX = startX + shaftLength / 2;

const arrowMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });

// Continuous cylinder for the shaft
const shaftGeom = new THREE.CylinderGeometry(shaftRadius, shaftRadius, shaftLength, 12);
const shaft = new THREE.Mesh(shaftGeom, arrowMat);
shaft.rotation.z = -Math.PI / 2;
shaft.position.x = shaftCenterX;
rayGroup.add(shaft);

// Arrowheads locations: one before each camera, and one at the final end
const tipXs = [];
for (let i = 0; i < numCameras; i++) {
  // Place tip slightly before the pinhole to prevent overlapping/engulfing the sphere
  tipXs.push(i * spacing - 0.15); 
}
tipXs.push(endX); 

const headGeom = new THREE.ConeGeometry(headRadius, headLength, 12);

tipXs.forEach((tipX) => {
  const head = new THREE.Mesh(headGeom, arrowMat);
  head.rotation.z = -Math.PI / 2;
  // Offset by half the length so the physical tip aligns exactly with tipX
  head.position.x = tipX - (headLength / 2);
  rayGroup.add(head);
});

registerInteractive(rayGroup, {
  title: 'Optical Ray',
  body: 'A single continuous ray passing through the optical centers of the camera sequence.'
});

sceneElements.add(rayGroup);

// Set view: elevation 0 with orthographic projection ensures the ray and back-planes
// render perfectly horizontal and vertical on the screen, exactly matching the 2D source style.
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 45,
  elevationDeg: 0,
  heightFraction: 0.6,
  target: [shaftCenterX, 0, 0]
});
// @FIGURE_CODE_END

